import type { Column, Typed } from '../Column'

/**
 * Duration type representing a time span with days, hours, minutes, and seconds.
 * At least one field must be specified.
 */
export type Duration = {
    days?: number
    hours?: number
    minutes?: number
    seconds?: number
}

/**
 * Time of day type with hours, minutes, and seconds (no days).
 * At least one field must be specified.
 */
export type TimeOfDay = {
    hours?: number // 0-23
    minutes?: number // 0-59
    seconds?: number // 0-59
}

type DurationColumnType<Type extends Duration | string = Duration | string, Default extends Type = Type> = Column<
    Type,
    Default
>

type TimeColumnType<Type extends TimeOfDay | string = TimeOfDay | string, Default extends Type = Type> = Column<
    Type,
    Default
>

/**
 * A Column for a duration field.
 * Represents a time span with days, hours, minutes, and seconds.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 *
 * @example
 * ```typescript
 * const duration = DurationColumn({
 *     label: 'Duration',
 *     default: duration{ days: 2, hours: 3, minutes: 30, seconds: 0 },
 * })
 *
 * const timeout = DurationColumn({
 *     label: 'Timeout',
 *     default: '1970-01-03 03:30:00',
 * })
 * ```
 */
export function DurationColumn<
    const Type extends Duration | string = Duration | string,
    const Default extends Type = Type,
    const C extends DurationColumnType<Type, Default> = DurationColumnType<Type, Default>,
>(config: C & DurationColumnType<Type, Default>) {
    return config as Typed<Type, C>
}

/**
 * A Column for a time field.
 * Represents a time of day with hours, minutes, and seconds.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 *
 * @example
 * ```typescript
 * const startTime = TimeColumn({
 *     label: 'Start Time',
 *     default: time({ hours: 9, minutes: 0, seconds: 0 }),
 * })
 *
 * const endTime = TimeColumn({
 *     label: 'End Time',
 *     default: '1970-01-01 17:30:00',
 * })
 * ```
 */
export function TimeColumn<
    const Type extends TimeOfDay | string = TimeOfDay | string,
    const Default extends Type = Type,
    const C extends TimeColumnType<Type, Default> = TimeColumnType<Type, Default>,
>(config: C & TimeColumnType<Type, Default>) {
    return config as Typed<Type, C>
}
